export function searchArticles(query) {
  if (!query || query.length < 2) return [];

  const searchTerm = query.toLowerCase().trim();

  return searchIndex.filter(article => {
    const titleMatch = article.title.toLowerCase().includes(searchTerm);
    const descriptionMatch = article.description.toLowerCase().includes(searchTerm);
    const urlMatch = article.url.toLowerCase().includes(searchTerm);

    return titleMatch || descriptionMatch || urlMatch;
  }).slice(0, 8); // Limiter à 8 résultats maximum
}
